/* --- STYLIZACJA PREMIUM MODERN (ELOK STYLE) --- */

.legal-premium-wrapper {
    position: relative;
    font-family: 'Inter', sans-serif;
    color: #b0b0b0;
    background-color: #000000;
    padding: 80px 20px;
    min-height: 100vh;
    overflow: hidden;
}

/* TŁO I GLOW */
.legal-glow {
    position: absolute; top: 0; left: 50%; transform: translateX(-50%);
    width: 800px; height: 500px;
    background: radial-gradient(circle, rgba(197, 160, 89, 0.15) 0%, transparent 70%);
    filter: blur(100px); z-index: 0; pointer-events: none;
}

.legal-container {
    position: relative; z-index: 1;
    max-width: 800px; margin: 0 auto;
}

/* NAGŁÓWEK */
.legal-header-modern { text-align: center; margin-bottom: 50px; }

.gradient-title {
    font-family: 'Outfit', sans-serif;
    font-size: 48px;
    font-weight: 700;
    margin: 0 0 10px 0;
    text-transform: uppercase;
    letter-spacing: -1px;
    color: white;
}

.subtitle {
    font-size: 14px; color: #C5A059; letter-spacing: 2px; font-weight: 600; text-transform: uppercase; margin-bottom: 20px;
}

.meta-badge {
    display: inline-flex; align-items: center; justify-content: center; gap: 10px;
    background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1);
    padding: 8px 20px; border-radius: 50px; font-size: 12px; color: #666; font-family: monospace;
}
.meta-badge .divider { color: #333; }

/* KARTA Z TREŚCIĄ (GLASS) */
.legal-card {
    background: #0a0a0a;
    border: 1px solid #1a1a1a;
    border-radius: 16px;
    padding: 60px;
    box-shadow: 0 20px 50px rgba(0,0,0,0.5);
}

.preamble {
    font-size: 18px; line-height: 1.6; color: #ddd; margin-bottom: 40px; text-align: center;
    max-width: 600px; margin-left: auto; margin-right: auto;
}

.section-divider {
    width: 100%; height: 1px;
    background: linear-gradient(to right, transparent, #222, transparent);
    margin: 40px 0;
}

/* SEKCJE */
.legal-section { margin-bottom: 50px; }

.legal-section h2 {
    font-family: 'Outfit', sans-serif;
    font-size: 20px;
    color: #C5A059;
    margin-bottom: 20px;
    text-transform: uppercase;
    letter-spacing: 1px;
    display: flex; align-items: center; gap: 10px;
}
/* Ozdobna kropka przy nagłówku */
.legal-section h2::before {
    content: ''; display: block; width: 6px; height: 6px; background: #C5A059; border-radius: 50%;
    box-shadow: 0 0 10px #C5A059;
}

.legal-section p {
    font-size: 15px; line-height: 1.7; color: #aaa; margin-bottom: 15px; text-align: justify;
}

.legal-section strong { color: #fff; font-weight: 600; }

/* STOPKA DOKUMENTU */
.legal-footer {
    text-align: center; font-size: 12px; color: #444; margin-top: 40px; text-transform: uppercase; letter-spacing: 1px;
}

/* RWD */
@media(max-width: 768px) {
    .legal-premium-wrapper { padding: 40px 15px; }
    .gradient-title { font-size: 32px; }
    .legal-card { padding: 30px 20px; }
    .preamble { font-size: 16px; text-align: left; }
    .legal-section h2 { font-size: 18px; }
    .legal-section p { font-size: 14px; text-align: left; }
}
